<template><q-page class="customer-flow-page profile-page" :class="`profile-section-${mobileSection}`"><div class="page-heading"><div><div class="eyebrow">YOUR BEMBANK</div><h1 class="page-title">Profile & security</h1><p class="page-subtitle">Your details and the keys to your account.</p></div></div><q-banner v-if="error" class="bg-red-1 text-red-9 q-mb-md">{{ error }}</q-banner><div class="mobile-profile-menu"><div class="profile-identity"><ProfilePhotoEditor size="58px" /><div><strong>{{ auth.fullName || auth.username }}</strong><small>{{ profile.email || auth.username }}</small></div></div><q-list><q-item clickable @click="editProfile"><q-item-section avatar><q-icon name="account_circle" /></q-item-section><q-item-section>Personal Information</q-item-section><q-item-section side><q-icon name="chevron_right" /></q-item-section></q-item><q-item v-for="item in profileSections.filter(section => section.key !== 'preferences')" :key="item.key" clickable :aria-expanded="mobileSection === item.key" @click="mobileSection = mobileSection === item.key ? '' : item.key"><q-item-section avatar><q-icon :name="item.icon" /></q-item-section><q-item-section>{{ item.label }}</q-item-section><q-item-section side><q-icon name="chevron_right" /></q-item-section></q-item><q-item clickable to="/customer/notifications"><q-item-section avatar><q-icon name="notifications_none" /></q-item-section><q-item-section>Notifications</q-item-section><q-item-section side><q-icon name="chevron_right" /></q-item-section></q-item><q-item clickable :aria-expanded="mobileSection === 'preferences'" @click="mobileSection = mobileSection === 'preferences' ? '' : 'preferences'"><q-item-section avatar><q-icon name="settings" /></q-item-section><q-item-section>App Settings</q-item-section><q-item-section side><q-icon name="chevron_right" /></q-item-section></q-item><q-item clickable to="/help"><q-item-section avatar><q-icon name="help_outline" /></q-item-section><q-item-section>Help &amp; Support</q-item-section><q-item-section side><q-icon name="chevron_right" /></q-item-section></q-item><q-item clickable class="text-negative" @click="logout"><q-item-section avatar><q-icon name="logout" /></q-item-section><q-item-section>Log Out</q-item-section><q-item-section side><q-icon name="chevron_right" /></q-item-section></q-item></q-list></div><div class="customer-workspace-grid profile-details"><section class="customer-panel"><ProfilePhotoEditor size="64px" /><h2>{{ auth.fullName || auth.username }}</h2><q-list separator><q-item v-for="(value, label) in details" :key="label"><q-item-section><q-item-label caption>{{ label }}</q-item-label><q-item-label>{{ value }}</q-item-label></q-item-section></q-item></q-list><q-btn outline color="primary" label="Edit profile" class="q-mt-md" @click="editProfile" /></section><section class="customer-panel"><h2 class="section-heading">Change your password</h2><p class="page-subtitle q-mb-lg">Use a long, unique password. Changing your password signs you out on all devices.</p><q-form class="customer-form" @submit="changePassword"><q-input v-model="current" filled type="password" label="Current password" autocomplete="current-password" :rules="[v => !!v || 'Required']" /><NewPasswordField v-model="next" label="New password" /><q-input v-model="confirm" filled type="password" label="Confirm new password" autocomplete="new-password" :rules="[v => v === next || 'Passwords must match']" /><q-btn color="primary" label="Update password" type="submit" :loading="saving" /></q-form></section></div><OtpManager class="profile-otp" @changed="securityVersion++" /><SessionManager class="profile-sessions" :key="securityVersion" /><AppPreferences class="profile-preferences" /><q-btn v-if="auth.isCustomer" flat color="negative" icon="logout" label="Sign out" class="desktop-profile-logout q-mt-lg" @click="logout" /><q-dialog v-model="profileOpen"><q-card style="width:460px;max-width:95vw"><q-form @submit="saveProfile"><q-card-section class="q-gutter-md"><h2 class="section-heading">Edit profile</h2><q-banner v-if="profileError" class="bank-feedback">{{ profileError }}</q-banner><q-input v-model.trim="profileForm.first_name" filled label="First name" maxlength="100" :rules="[v => !!v || 'Required']" /><q-input v-model.trim="profileForm.last_name" filled label="Last name" maxlength="100" :rules="[v => !!v || 'Required']" /><q-input v-model.trim="profileForm.email" filled label="Email" type="email" /><q-input v-model.trim="profileForm.mobile_number" filled label="Mobile number" type="tel" maxlength="30" /></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" :disable="savingProfile" v-close-popup /><q-btn color="primary" label="Save profile" type="submit" :loading="savingProfile" /></q-card-actions></q-form></q-card></q-dialog></q-page></template>
<script setup>
import ProfilePhotoEditor from '@/components/ProfilePhotoEditor.vue'
import AppPreferences from '@/components/AppPreferences.vue'
import NewPasswordField from '@/components/NewPasswordField.vue'
import { ref, computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useQuasar } from 'quasar'
import { useAuthStore } from '@/stores/auth-store'
import api from '@/services/api'
import SessionManager from '@/components/SessionManager.vue'
import OtpManager from '@/components/OtpManager.vue'
const securityVersion = ref(0)
const mobileSection = ref('')
const profileSections = [{ key: 'security', label: 'Account Security', icon: 'lock_outline' }, { key: 'sessions', label: 'Linked Devices', icon: 'devices' }, { key: 'preferences', label: 'App Settings', icon: 'settings' }]
async function logout () { await auth.logout(); router.replace('/login') }
const profileOpen = ref(false), profileForm = ref({}), profileError = ref(''), savingProfile = ref(false)
const auth = useAuthStore(), router = useRouter(), $q = useQuasar(), profile = ref({}), current = ref(''), next = ref(''), confirm = ref(''), error = ref(''), saving = ref(false)
const details = computed(() => ({ Username: auth.username, Email: profile.value.email || '—', Mobile: profile.value.mobile_number || '—', Role: auth.roleName, Status: profile.value.account_status || '—' }))
onMounted(async () => { try { profile.value = (await api.get('/auth/me')).data } catch { error.value = 'Could not load your profile.' } })
async function changePassword () { saving.value = true; error.value = ''; try { await api.post('/auth/password', { current_password: current.value, new_password: next.value }); await auth.logout(); $q.notify({ type: 'positive', message: 'Password changed. Sign in again to continue.' }); router.replace('/login') } catch (e) { error.value = typeof e.response?.data?.detail === 'string' ? e.response.data.detail : 'Could not update your password.' } finally { saving.value = false } }
function editProfile () { profileError.value = ''; profileForm.value = { first_name: profile.value.first_name || auth.firstName || '', last_name: profile.value.last_name || auth.lastName || '', email: profile.value.email || '', mobile_number: profile.value.mobile_number || '' }; profileOpen.value = true }
async function saveProfile () { savingProfile.value = true; profileError.value = ''; try { const { data } = await api.put('/auth/profile', { ...profileForm.value, email: profileForm.value.email || null, mobile_number: profileForm.value.mobile_number || null }); profile.value = data; auth.firstName = data.first_name; auth.lastName = data.last_name; auth.persist(); profileOpen.value = false; $q.notify({ type: 'positive', message: 'Profile updated' }) } catch (e) { profileError.value = typeof e.response?.data?.detail === 'string' ? e.response.data.detail : 'Profile could not be updated.' } finally { savingProfile.value = false } }
</script>
